# app/metrics.py
from __future__ import annotations

import os
from typing import Dict, Any

from fastapi import APIRouter, Response, Header, HTTPException
from pydantic import BaseModel
from prometheus_client import (
    Counter,
    Gauge,
    Summary,
    generate_latest,
    CONTENT_TYPE_LATEST,
)

router = APIRouter()

# Route-level metrics
route_requests_total = Counter(
    "route_requests_total", "Total requests to scoring routes", ["path", "status"]
)
route_labels_generated_total = Counter(
    "route_labels_generated_total", "Total labels generated by /route"
)
route_latency_seconds = Summary(
    "route_latency_seconds", "Latency of /route handler in seconds"
)

# Ingest/runner-level metrics (received via POST /ingest_metrics)
events_fetched_total = Counter(
    "events_fetched_total", "Events fetched (pre-dedupe)", ["source"]
)
leads_emitted_total = Counter(
    "leads_emitted_total", "Leads emitted to legacy leads.csv"
)
shadow_leads_total = Counter(
    "shadow_leads_total", "Leads above threshold in shadow (leads_v2)"
)
predicted_revenue = Gauge(
    "predicted_revenue", "Sum of predicted revenue for current run"
)


class IngestMetricsIn(BaseModel):
    events_fetched: Dict[str, int] | None = None
    leads_emitted: int | None = 0
    shadow_leads: int | None = 0
    predicted_revenue_sum: float | None = 0.0


@router.get("/metrics")
def metrics() -> Response:
    return Response(generate_latest(), media_type=CONTENT_TYPE_LATEST)


@router.post("/ingest_metrics")
def ingest_metrics(payload: IngestMetricsIn, x_ingest_key: str | None = Header(default=None, alias="X-Ingest-Key")) -> Dict[str, Any]:
    expected = os.environ.get("INGEST_METRICS_KEY")
    if not expected or x_ingest_key != expected:
        raise HTTPException(status_code=401, detail="Unauthorized")

    data = payload.dict() if payload else {}
    for src, cnt in (data.get("events_fetched") or {}).items():
        try:
            events_fetched_total.labels(source=str(src)).inc(float(cnt))
        except Exception:
            # ignore bad inputs
            pass
    if data.get("leads_emitted"):
        try:
            leads_emitted_total.inc(float(data.get("leads_emitted", 0)))
        except Exception:
            pass
    if data.get("shadow_leads"):
        try:
            shadow_leads_total.inc(float(data.get("shadow_leads", 0)))
        except Exception:
            pass
    if data.get("predicted_revenue_sum") is not None:
        try:
            predicted_revenue.set(float(data.get("predicted_revenue_sum", 0.0)))
        except Exception:
            pass

    return {"status": "ok"}
